/**
 * ASAKA ZIYO — Complete Audited Telegram Inline Callback Query Router
 *
 * Every inline button generated by `keyboards.ts` routes to a real working handler:
 * - Navigation: nav:home | nav:prayer | nav:quran | nav:hadith | nav:dhikr | nav:ai | nav:profile | nav:language | nav:settings | nav:channels | nav:help
 * - Prayer: prayer:refresh
 * - Quran: quran:ayah:<idx> | quran:surahs | quran:surah:<num>
 * - Hadith: hadith:view:<idx>
 * - Dhikr & Tasbeh: dhikr:view:<idx> | dhikr:tasbeh:<idx>:<count>
 * - AI: ai:exit
 * - Language: lang:<uz-Latn|uz-Cyrl|uz-Latn-new|ru|en>
 * - Settings: settings:toggle:<prayerNotificationsEnabled|dailyWisdomEnabled|announcementsEnabled>
 * - Admin (RBAC-protected): admin:home | admin:channels | admin:channel:check:<id> |
 *   admin:channel:publish_prayer:<id> | admin:channel:toggle_auto:<id> | admin:emojis |
 *   admin:emojis:verify | admin:emojis:test | admin:ai:toggle | admin:maintenance:toggle | admin:diagnostics
 */

import {
  TelegramApiCallbackQuery,
  TelegramInlineKeyboardMarkup,
  TelegramMessageEntity,
  TelegramUserRecord,
} from '../types';
import { TelegramPlatformConfig } from '../config';
import { TelegramApiClient } from '../api/telegramApiClient';
import { CustomEmojiRegistry } from '../emoji/customEmojiRegistry';
import { TelegramUserService } from '../services/userService';
import { TelegramPrayerAdapter } from '../prayer/prayerAdapter';
import { TelegramIslamicContentAdapter } from '../content/islamicContentAdapter';
import { TelegramAiBridge } from '../ai/aiBridge';
import { TelegramAdminService } from '../admin/adminService';
import { TelegramChannelService } from '../channels/channelService';
import { TelegramPublishingService } from '../publishing/publishingService';
import { TelegramRepository } from '../database/telegramRepository';
import { getTelegramLocaleBundle, isValidTelegramLocale } from '../locales';
import {
  buildAdminChannelsKeyboard,
  buildAdminEmojisKeyboard,
  buildAdminHomeKeyboard,
  buildAiModeKeyboard,
  buildBackOnlyKeyboard,
  buildChannelsKeyboard,
  buildDhikrKeyboard,
  buildHadithKeyboard,
  buildLanguageKeyboard,
  buildMainMenuKeyboard,
  buildPrayerKeyboard,
  buildProfileKeyboard,
  buildQuranKeyboard,
  buildSettingsKeyboard,
  buildSurahListKeyboard,
} from '../keyboards/keyboards';
import {
  formatAdminOverviewText,
  formatProfileMessageText,
  formatSettingsMessageText,
} from './commandHandlers';

export interface CallbackHandlerContext {
  apiClient: TelegramApiClient;
  config: TelegramPlatformConfig;
  emojiRegistry: CustomEmojiRegistry;
  userService: TelegramUserService;
  prayerAdapter: TelegramPrayerAdapter;
  contentAdapter: TelegramIslamicContentAdapter;
  aiBridge: TelegramAiBridge;
  adminService: TelegramAdminService;
  channelService: TelegramChannelService;
  publishingService: TelegramPublishingService;
  repository: TelegramRepository;
  runDiagnostics: () => Promise<{
    readyToAnswerStart: boolean;
    mode: string;
    startupState: string;
    telegramApi: { connected: boolean; botUsername?: string; error?: string };
    issues: string[];
  }>;
}

async function renderScreenUpdate(
  apiClient: TelegramApiClient,
  callback: TelegramApiCallbackQuery,
  payload: {
    text: string;
    entities?: TelegramMessageEntity[];
    reply_markup: TelegramInlineKeyboardMarkup;
  }
) {
  const chatId = callback.message?.chat.id || callback.from.id;
  const messageId = callback.message?.message_id;

  if (messageId) {
    const edited = await apiClient.editMessageText({
      chat_id: chatId,
      message_id: messageId,
      text: payload.text,
      ...(payload.entities && payload.entities.length > 0 ? { entities: payload.entities } : {}),
      reply_markup: payload.reply_markup,
      disable_web_page_preview: true,
    });
    if (edited.ok) return;
  }

  await apiClient.sendMessage({
    chat_id: chatId,
    text: payload.text,
    ...(payload.entities && payload.entities.length > 0 ? { entities: payload.entities } : {}),
    reply_markup: payload.reply_markup,
    disable_web_page_preview: true,
  });
}

export async function handleCallbackQuery(
  callback: TelegramApiCallbackQuery,
  user: TelegramUserRecord,
  ctx: CallbackHandlerContext
): Promise<{ handled: boolean; action: string }> {
  const data = (callback.data || '').trim();
  const dict = getTelegramLocaleBundle(user.language);
  const role = ctx.adminService.getEffectiveRole(user.telegramId);
  const settings = ctx.repository.getSettings();
  const menuOpts = { isAdmin: Boolean(role), miniAppEnabled: Boolean(settings.miniAppEnabled) };

  // Exit AI session when navigating away from AI screen
  if (data !== 'nav:ai') {
    ctx.aiBridge.exitAiMode(user.telegramId);
  }

  // 1. Language Selection: lang:<locale>
  if (data.startsWith('lang:')) {
    const requestedLocale = data.slice('lang:'.length);
    if (!isValidTelegramLocale(requestedLocale)) {
      await ctx.apiClient.answerCallbackQuery({
        callback_query_id: callback.id,
        text: dict.genericError,
      });
      return { handled: true, action: 'lang:invalid' };
    }

    const updatedUser =
      (await ctx.userService.setUserLanguage(user.telegramId, requestedLocale)) || {
        ...user,
        language: requestedLocale,
      };
    const nextDict = getTelegramLocaleBundle(updatedUser.language);
    const formatted = ctx.emojiRegistry.formatMessage(
      `${nextDict.languageChangedMessage}\n\n${nextDict.mainMenuPrompt}`
    );

    await ctx.apiClient.answerCallbackQuery({
      callback_query_id: callback.id,
      text: nextDict.languageChangedToast,
    });
    await renderScreenUpdate(ctx.apiClient, callback, {
      text: formatted.text,
      entities: formatted.entities,
      reply_markup: buildMainMenuKeyboard(updatedUser.language, ctx.emojiRegistry, ctx.config, menuOpts),
    });
    return { handled: true, action: `lang:${requestedLocale}` };
  }

  // 2. Settings Toggles: settings:toggle:<field>
  if (data.startsWith('settings:toggle:')) {
    const field = data.slice('settings:toggle:'.length);
    if (
      field === 'prayerNotificationsEnabled' ||
      field === 'dailyWisdomEnabled' ||
      field === 'announcementsEnabled'
    ) {
      const updatedUser =
        (await ctx.userService.toggleSetting(user.telegramId, field)) || user;
      const nextDict = getTelegramLocaleBundle(updatedUser.language);
      const formatted = formatSettingsMessageText(updatedUser, ctx.emojiRegistry);

      await ctx.apiClient.answerCallbackQuery({
        callback_query_id: callback.id,
        text: nextDict.settingUpdatedToast,
      });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildSettingsKeyboard(updatedUser, ctx.emojiRegistry),
      });
      return { handled: true, action: `settings:toggle:${field}` };
    }
  }

  // 3. Quran Callbacks: quran:ayah:<idx> | quran:surahs | quran:surah:<num>
  if (data.startsWith('quran:ayah:')) {
    const idx = Number(data.slice('quran:ayah:'.length)) || 0;
    const res = ctx.contentAdapter.formatQuranDailyAyah(idx, user.language, ctx.emojiRegistry);
    await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
    await renderScreenUpdate(ctx.apiClient, callback, {
      text: res.formatted.text,
      entities: res.formatted.entities,
      reply_markup: buildQuranKeyboard(
        user.language,
        res.index,
        res.total,
        ctx.emojiRegistry,
        ctx.config,
        menuOpts.miniAppEnabled
      ),
    });
    return { handled: true, action: data };
  }

  if (data === 'quran:surahs') {
    const surahs = ctx.contentAdapter.getFeaturedSurahs();
    const formatted = ctx.emojiRegistry.formatMessage(
      `${dict.quranTitle}\n\n{{emoji:brand.book}} ${dict.buttons.surahList}:`
    );
    await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
    await renderScreenUpdate(ctx.apiClient, callback, {
      text: formatted.text,
      entities: formatted.entities,
      reply_markup: buildSurahListKeyboard(user.language, surahs, ctx.emojiRegistry),
    });
    return { handled: true, action: 'quran:surahs' };
  }

  if (data.startsWith('quran:surah:')) {
    const num = Number(data.slice('quran:surah:'.length)) || 1;
    const formatted = ctx.contentAdapter.formatSurahCard(num, user.language, ctx.emojiRegistry);
    const surahs = ctx.contentAdapter.getFeaturedSurahs();
    await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
    await renderScreenUpdate(ctx.apiClient, callback, {
      text: formatted.text,
      entities: formatted.entities,
      reply_markup: buildSurahListKeyboard(user.language, surahs, ctx.emojiRegistry),
    });
    return { handled: true, action: data };
  }

  // 4. Hadith Callbacks: hadith:view:<idx>
  if (data.startsWith('hadith:view:')) {
    const idx = Number(data.slice('hadith:view:'.length)) || 0;
    const res = ctx.contentAdapter.formatHadithCard(idx, user.language, ctx.emojiRegistry);
    await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
    await renderScreenUpdate(ctx.apiClient, callback, {
      text: res.formatted.text,
      entities: res.formatted.entities,
      reply_markup: buildHadithKeyboard(user.language, res.index, res.total, ctx.emojiRegistry),
    });
    return { handled: true, action: data };
  }

  // 5. Dhikr & Interactive Tasbeh Callbacks: dhikr:view:<idx> | dhikr:tasbeh:<idx>:<count>
  if (data.startsWith('dhikr:view:')) {
    const idx = Number(data.slice('dhikr:view:'.length)) || 0;
    const res = ctx.contentAdapter.formatDhikrCard(idx, 0, user.language, ctx.emojiRegistry);
    await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
    await renderScreenUpdate(ctx.apiClient, callback, {
      text: res.formatted.text,
      entities: res.formatted.entities,
      reply_markup: buildDhikrKeyboard(user.language, res.index, res.total, 0, ctx.emojiRegistry),
    });
    return { handled: true, action: data };
  }

  if (data.startsWith('dhikr:tasbeh:')) {
    const parts = data.split(':');
    const idx = Number(parts[2]) || 0;
    const nextCount = Math.max(0, Math.min(9999, Number(parts[3]) || 0));
    const res = ctx.contentAdapter.formatDhikrCard(idx, nextCount, user.language, ctx.emojiRegistry);
    await ctx.apiClient.answerCallbackQuery({
      callback_query_id: callback.id,
      text: `${nextCount} / ${res.targetCount}`,
    });
    await renderScreenUpdate(ctx.apiClient, callback, {
      text: res.formatted.text,
      entities: res.formatted.entities,
      reply_markup: buildDhikrKeyboard(
        user.language,
        res.index,
        res.total,
        nextCount,
        ctx.emojiRegistry
      ),
    });
    return { handled: true, action: `dhikr:tasbeh:${idx}:${nextCount}` };
  }

  // 6. RBAC-Protected Admin Callbacks: admin:*
  if (data.startsWith('admin:')) {
    if (!role) {
      await ctx.repository.appendAuditLog({
        actorTelegramId: user.telegramId,
        actorRole: 'user',
        action: 'admin_callback_denied',
        targetType: 'admin',
        targetId: data,
      });
      await ctx.apiClient.answerCallbackQuery({
        callback_query_id: callback.id,
        text: dict.adminAccessDenied,
        show_alert: true,
      });
      return { handled: true, action: 'admin:denied' };
    }

    if (data === 'admin:home') {
      const formatted = formatAdminOverviewText(
        user.language,
        ctx.repository,
        ctx.emojiRegistry,
        ctx.aiBridge
      );
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildAdminHomeKeyboard(user.language, settings, ctx.emojiRegistry),
      });
      return { handled: true, action: 'admin:home' };
    }

    if (data === 'admin:ai:toggle') {
      const updated = await ctx.repository.saveSettings(
        { aiAssistantEnabled: !settings.aiAssistantEnabled },
        user.telegramId
      );
      const formatted = formatAdminOverviewText(
        user.language,
        ctx.repository,
        ctx.emojiRegistry,
        ctx.aiBridge
      );
      await ctx.apiClient.answerCallbackQuery({
        callback_query_id: callback.id,
        text: dict.settingUpdatedToast,
      });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildAdminHomeKeyboard(user.language, updated, ctx.emojiRegistry),
      });
      return { handled: true, action: 'admin:ai:toggle' };
    }

    if (data === 'admin:maintenance:toggle') {
      const updated = await ctx.repository.saveSettings(
        { maintenanceMode: !settings.maintenanceMode },
        user.telegramId
      );
      const formatted = formatAdminOverviewText(
        user.language,
        ctx.repository,
        ctx.emojiRegistry,
        ctx.aiBridge
      );
      await ctx.apiClient.answerCallbackQuery({
        callback_query_id: callback.id,
        text: dict.settingUpdatedToast,
      });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildAdminHomeKeyboard(user.language, updated, ctx.emojiRegistry),
      });
      return { handled: true, action: 'admin:maintenance:toggle' };
    }

    if (data === 'admin:channels') {
      const channels = ctx.channelService.listChannels();
      const chLines = channels.map(
        (c) =>
          `• ${c.username} (${c.title}) — ${c.autoPublishPrayerTimes ? 'Auto-Namoz ON' : 'Auto-Namoz OFF'}`
      );
      const formatted = ctx.emojiRegistry.formatMessage(
        `${dict.adminChannelsTitle}\n\n${chLines.join('\n')}`
      );
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildAdminChannelsKeyboard(user.language, channels, ctx.emojiRegistry),
      });
      return { handled: true, action: 'admin:channels' };
    }

    if (data.startsWith('admin:channel:check:')) {
      const chId = data.slice('admin:channel:check:'.length);
      const perm = await ctx.publishingService.verifyChannelPermissions(chId);
      await ctx.apiClient.answerCallbackQuery({
        callback_query_id: callback.id,
        text: perm.reason.slice(0, 190),
        show_alert: true,
      });
      return { handled: true, action: `admin:channel:check:${chId}` };
    }

    if (data.startsWith('admin:channel:publish_prayer:')) {
      const chId = data.slice('admin:channel:publish_prayer:'.length);
      const pub = await ctx.publishingService.publishPrayerScheduleToChannel({
        channelId: chId,
        prayerAdapter: ctx.prayerAdapter,
        createdBy: user.telegramId,
      });
      await ctx.apiClient.answerCallbackQuery({
        callback_query_id: callback.id,
        text: pub.success ? 'Namoz jadvali kanalga yuborildi!' : (pub.error || 'Xatolik').slice(0, 190),
        show_alert: true,
      });
      return { handled: true, action: `admin:channel:publish_prayer:${chId}` };
    }

    if (data.startsWith('admin:channel:toggle_auto:')) {
      const chId = data.slice('admin:channel:toggle_auto:'.length);
      const existing = ctx.repository.getChannel(chId);
      if (existing) {
        await ctx.channelService.upsertChannel(user.telegramId, {
          ...existing,
          autoPublishPrayerTimes: !existing.autoPublishPrayerTimes,
        });
      }
      const channels = ctx.channelService.listChannels();
      const chLines = channels.map(
        (c) =>
          `• ${c.username} (${c.title}) — ${c.autoPublishPrayerTimes ? 'Auto-Namoz ON' : 'Auto-Namoz OFF'}`
      );
      const formatted = ctx.emojiRegistry.formatMessage(
        `${dict.adminChannelsTitle}\n\n${chLines.join('\n')}`
      );
      await ctx.apiClient.answerCallbackQuery({
        callback_query_id: callback.id,
        text: dict.settingUpdatedToast,
      });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildAdminChannelsKeyboard(user.language, channels, ctx.emojiRegistry),
      });
      return { handled: true, action: `admin:channel:toggle_auto:${chId}` };
    }

    if (data === 'admin:emojis') {
      const rep = ctx.emojiRegistry.validateCompatibility();
      const formatted = ctx.emojiRegistry.formatMessage(
        `${dict.adminEmojisTitle}\n\n` +
          `• Jami semantik slotlar: ${rep.totalRegisteredKeys}\n` +
          `• Tasdiqlangan Custom ID: ${rep.verifiedCustomCount}\n` +
          `• Unicode Fallback: ${rep.fallbackOnlyCount}\n` +
          `• Premium Rendering: ${rep.premiumRenderingActive ? 'ON' : 'OFF (Unicode fallback)'}\n` +
          `• Keyboard Custom Icon: ${rep.keyboardCustomIconsActive ? 'ON' : 'OFF (Unicode fallback)'}`
      );
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildAdminEmojisKeyboard(user.language, ctx.emojiRegistry),
      });
      return { handled: true, action: 'admin:emojis' };
    }

    if (data === 'admin:emojis:verify') {
      const ver = await ctx.emojiRegistry.verifyAllWithTelegramApi(ctx.apiClient);
      await ctx.apiClient.answerCallbackQuery({
        callback_query_id: callback.id,
        text: `API: ${ver.apiAvailable ? 'OK' : 'OFF'} | Verified: ${ver.verifiedKeys.length} | Rejected: ${ver.rejectedKeys.length}`,
        show_alert: true,
      });
      return { handled: true, action: 'admin:emojis:verify' };
    }

    if (data === 'admin:emojis:test') {
      const chatId = callback.message?.chat.id || callback.from.id;
      const testRes = await ctx.emojiRegistry.sendLiveEmojiTestMessage(ctx.apiClient, chatId);
      await ctx.apiClient.answerCallbackQuery({
        callback_query_id: callback.id,
        text: testRes.ok
          ? `Test yuborildi (Custom: ${testRes.usedCustomEmojiCount}, Fallback: ${testRes.usedFallbackCount})`
          : (testRes.error || 'Yuborilmadi').slice(0, 180),
        show_alert: true,
      });
      return { handled: true, action: 'admin:emojis:test' };
    }

    if (data === 'admin:diagnostics') {
      const diag = await ctx.runDiagnostics();
      const issueText = diag.issues.length > 0 ? diag.issues.join('\n• ') : 'Hech qanday muammo topilmadi.';
      const formatted = ctx.emojiRegistry.formatMessage(
        `${dict.adminTitle}\n\n` +
          `• Mode: ${diag.mode} (${diag.startupState})\n` +
          `• Telegram API: ${diag.telegramApi.connected ? `@${diag.telegramApi.botUsername}` : diag.telegramApi.error}\n` +
          `• /start tayyorligi: ${diag.readyToAnswerStart ? 'TAYYOR' : 'TEKSHIRISH KERAK'}\n\n` +
          `• Holat: ${issueText}`
      );
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildAdminHomeKeyboard(user.language, settings, ctx.emojiRegistry),
      });
      return { handled: true, action: 'admin:diagnostics' };
    }
  }

  // 7. Standard Navigation & Content Views
  switch (data) {
    case 'nav:home':
    case 'ai:exit': {
      const formatted = ctx.emojiRegistry.formatMessage(
        `${dict.mainMenuTitle}\n\n${dict.mainMenuPrompt}`
      );
      await ctx.apiClient.answerCallbackQuery({
        callback_query_id: callback.id,
        ...(data === 'ai:exit' ? { text: dict.aiExitedToast } : {}),
      });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildMainMenuKeyboard(user.language, ctx.emojiRegistry, ctx.config, menuOpts),
      });
      return { handled: true, action: data };
    }

    case 'nav:prayer':
    case 'prayer:refresh': {
      const formatted = ctx.prayerAdapter.formatPrayerScheduleMessage(
        user.language,
        ctx.emojiRegistry
      );
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildPrayerKeyboard(
          user.language,
          ctx.emojiRegistry,
          ctx.config,
          menuOpts.miniAppEnabled
        ),
      });
      return { handled: true, action: data };
    }

    case 'nav:quran': {
      const res = ctx.contentAdapter.formatQuranDailyAyah(0, user.language, ctx.emojiRegistry);
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: res.formatted.text,
        entities: res.formatted.entities,
        reply_markup: buildQuranKeyboard(
          user.language,
          res.index,
          res.total,
          ctx.emojiRegistry,
          ctx.config,
          menuOpts.miniAppEnabled
        ),
      });
      return { handled: true, action: 'nav:quran' };
    }

    case 'nav:hadith': {
      const res = ctx.contentAdapter.formatHadithCard(0, user.language, ctx.emojiRegistry);
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: res.formatted.text,
        entities: res.formatted.entities,
        reply_markup: buildHadithKeyboard(user.language, res.index, res.total, ctx.emojiRegistry),
      });
      return { handled: true, action: 'nav:hadith' };
    }

    case 'nav:dhikr': {
      const res = ctx.contentAdapter.formatDhikrCard(0, 0, user.language, ctx.emojiRegistry);
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: res.formatted.text,
        entities: res.formatted.entities,
        reply_markup: buildDhikrKeyboard(user.language, res.index, res.total, 0, ctx.emojiRegistry),
      });
      return { handled: true, action: 'nav:dhikr' };
    }

    case 'nav:ai': {
      const aiStatus = ctx.aiBridge.getStatus();
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      if (!aiStatus.enabled) {
        const formatted = ctx.emojiRegistry.formatMessage(
          `${dict.aiTitle}\n\n${dict.aiDisabledNotice}`
        );
        await renderScreenUpdate(ctx.apiClient, callback, {
          text: formatted.text,
          entities: formatted.entities,
          reply_markup: buildBackOnlyKeyboard(user.language, ctx.emojiRegistry),
        });
        return { handled: true, action: 'nav:ai:disabled' };
      }
      if (!aiStatus.apiKeyConfigured) {
        const formatted = ctx.emojiRegistry.formatMessage(
          `${dict.aiTitle}\n\n${dict.aiMissingKeyNotice}`
        );
        await renderScreenUpdate(ctx.apiClient, callback, {
          text: formatted.text,
          entities: formatted.entities,
          reply_markup: buildBackOnlyKeyboard(user.language, ctx.emojiRegistry),
        });
        return { handled: true, action: 'nav:ai:missing_key' };
      }

      ctx.aiBridge.enterAiMode(user.telegramId);
      const formatted = ctx.emojiRegistry.formatMessage(
        `${dict.aiTitle}\n\n${dict.aiPromptReady}`
      );
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildAiModeKeyboard(user.language, ctx.emojiRegistry),
      });
      return { handled: true, action: 'nav:ai' };
    }

    case 'nav:profile': {
      const formatted = formatProfileMessageText(user, role, ctx.emojiRegistry);
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildProfileKeyboard(user.language, ctx.emojiRegistry),
      });
      return { handled: true, action: 'nav:profile' };
    }

    case 'nav:language': {
      const formatted = ctx.emojiRegistry.formatMessage(
        `${dict.languageTitle}\n\n${dict.languagePrompt}`
      );
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildLanguageKeyboard(user.language, ctx.emojiRegistry),
      });
      return { handled: true, action: 'nav:language' };
    }

    case 'nav:settings': {
      const formatted = formatSettingsMessageText(user, ctx.emojiRegistry);
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildSettingsKeyboard(user, ctx.emojiRegistry),
      });
      return { handled: true, action: 'nav:settings' };
    }

    case 'nav:channels': {
      const formatted = ctx.emojiRegistry.formatMessage(
        `${dict.channelsTitle}\n\n${dict.channelsBody}`
      );
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildChannelsKeyboard(user.language, ctx.emojiRegistry),
      });
      return { handled: true, action: 'nav:channels' };
    }

    case 'nav:help': {
      const formatted = ctx.emojiRegistry.formatMessage(
        `${dict.helpTitle}\n\n${dict.helpBody}`
      );
      await ctx.apiClient.answerCallbackQuery({ callback_query_id: callback.id });
      await renderScreenUpdate(ctx.apiClient, callback, {
        text: formatted.text,
        entities: formatted.entities,
        reply_markup: buildBackOnlyKeyboard(user.language, ctx.emojiRegistry),
      });
      return { handled: true, action: 'nav:help' };
    }

    default: {
      await ctx.apiClient.answerCallbackQuery({
        callback_query_id: callback.id,
        text: dict.unknownCommand,
      });
      return { handled: false, action: data || 'unknown' };
    }
  }
}
